\end{enumerate}

区間 $0\le x\le a$ 上の滑らかな関数のうち，境界条件 $\psi(a)=e^{i\theta}\psi(0)$（$\theta$ は実定数）をみたすもの全体を考える．内積は $\langle\psi|\phi\rangle=\int_0^a\psi^*\phi\,dx$ とする．
\begin{enumerate}
\item この関数空間で運動量演算子 $\hat p=-i\hbar\,\dfrac{d}{dx}$ がエルミートである（$\langle\psi|\hat p\phi\rangle=\langle\hat p\psi|\phi\rangle$）ことを示せ．また，境界条件を「$\psi(a)=\lambda\psi(0)$（$\lambda$ は複素定数）」に一般化したとき，$\hat p$ がエルミートであるための $\lambda$ の条件を求めよ．
\item この空間での $\hat p$ の固有値と規格化された固有関数をすべて求めよ．
\item 今度は全実軸上で $|x|\to\infty$ で十分速く $0$ になる\textbf{実数値}の規格化された関数 $\psi(x)$ を考える．$\langle\psi|\hat x\hat p\,\psi\rangle$ を求め，$\hat x\hat p$ がエルミートでないことを示せ．さらに $\hat D=\frac12(\hat x\hat p+\hat p\hat x)$ の期待値がこの $\psi$ に対して $0$ になることを示せ．
\end{enumerate}

$\hat x,\hat p$ はエルミートで $[\hat x,\hat p]=i\hbar$ をみたす．
\begin{enumerate}
\item 任意の演算子 $\hat A,\hat B$ について $(\hat A\hat B)^\dagger=\hat B^\dagger\hat A^\dagger$，$(\hat A^\dagger)^\dagger=\hat A$ を示し，これを用いて $\hat A,\hat B$ がエルミートなら $i[\hat A,\hat B]$ もエルミートであることを示せ．
\item 演算子 $\hat x\hat p^2$ をエルミート部分 $\hat H_1=\frac12(\hat x\hat p^2+(\hat x\hat p^2)^\dagger)$ と反エルミート部分 $\hat K=\frac12(\hat x\hat p^2-(\hat x\hat p^2)^\dagger)$ に分ける．$\hat H_1=\hat p\hat x\hat p$，$\hat K=i\hbar\hat p$ であることを示せ．
\item 規格化された波束 $\psi(x)=(\pi\sigma^2)^{-1/4}\exp\!\left[-\dfrac{(x-x_0)^2}{2\sigma^2}+ik_0x\right]$（$x_0,k_0$ 実数，$\sigma>0$）について $\langle\psi|\hat x\hat p^2\psi\rangle$ を求め，その実部と虚部が (2) の分解とどう対応するか述べよ．
\end{enumerate}

半径一定の円環上を運動する粒子（平面回転子）を考える．角運動量の $z$ 成分は $\hat l_z=-i\hbar\,\partial/\partial\varphi$，ハミルトニアンは $\hat H=\hat l_z^2/(2I)$（$I$ は慣性モーメント）である．
\begin{enumerate}
\item 周期境界条件 $\Phi(\varphi+2\pi)=\Phi(\varphi)$ のもとで $\hat l_z$ の規格化された固有関数と固有値を求め，$\hat H$ の各準位の縮退度を述べよ．
\item 円環の $\varphi=0$ の位置に無限に高く薄い障壁を置き，$\psi(0)=\psi(2\pi)=0$（$0<\varphi<2\pi$）とする．$\hat H$ のエネルギー固有値と規格化固有関数を求めよ．基底エネルギーは (1) の場合と比べてどうなるか．
\item (2) の基底状態にある粒子について（障壁を取り去った直後に）$l_z$ を測定する．値 $m\hbar$ が得られる確率 $P_m$ を求め，$P_0$ の数値を示せ．また $\sum_m m^2\hbar^2P_m$ が (2) の基底エネルギーの $2I$ 倍に一致することを確かめよ．半整数値 $\hbar/2$ が観測されないことにも注意せよ．
\end{enumerate}

慣性モーメント $I$ の剛体回転子（$\hat H=\hat{\boldsymbol l}^2/2I$，固有関数 $Y_{lm}$，$Y_{l0}=\sqrt{\frac{2l+1}{4\pi}}P_l(\cos\theta)$）が時刻 $t=0$ に
\[
\psi(\theta,\varphi,0)=\begin{cases}1/\sqrt{2\pi}&(0\le\theta<\pi/2)\\0&(\pi/2<\theta\le\pi)\end{cases}
\]
の状態にある．ルジャンドル多項式の直交性 $\int_{-1}^1P_lP_{l'}dz=\frac{2}{2l+1}\delta_{ll'}$，関係式 $(2l+1)P_l=P_{l+1}'-P_{l-1}'$，および $P_{2k}(0)=(-1)^kg_k$，$g_k=\dfrac{(2k)!}{4^k(k!)^2}$ を用いてよい．
\begin{enumerate}
\item $\hat{\boldsymbol l}^2$ を測定して $l(l+1)\hbar^2$ を得る確率 $p_l$ を $\int_0^1P_l(z)dz$ で表し，$p_0,p_1,p_2,p_3$ を求めよ．$l\ge2$ の偶数では $p_l=0$ となることを示せ．
\item 奇数 $l=2k+1$ に対し $p_l=\dfrac{2l+1}{2}\dfrac{g_k^2}{(l+1)^2}$ を示し，$g_k\simeq1/\sqrt{\pi k}$ を用いて $l\to\infty$ での漸近形を求めよ．これからエネルギー期待値はどうなるか．
\item $\langle\cos\theta\rangle(t)$ を求めよ．エネルギー期待値の結果と対比して，その特徴を述べよ．
\end{enumerate}

クーロンポテンシャル $V(r)=-\dfrac{e^2}{r}$ に束縛された質量 $m$ の粒子を考え，$a=\dfrac{\hbar^2}{me^2}$ とする．
\begin{enumerate}
\item 角運動量 $l$ の状態について，動径関数を $R(r)=r^{l}e^{-\beta r}$ とおくと解になることを示し，$\beta$ とエネルギー $E$ を $l$ と $a$ で表せ．このエネルギーは主量子数 $n$ でいうとどの準位か．
\item この状態で，動径確率密度 $r^2|R|^2$ が最大となる半径 $r_{\mathrm{mp}}$ を求め，ボーア模型の軌道半径と比較せよ．
\item $\langle r\rangle$ と $\Delta r=\sqrt{\langle r^2\rangle-\langle r\rangle^2}$ を求め，相対ゆらぎ $\Delta r/\langle r\rangle$ が $l\to\infty$ でどう振る舞うか答えよ．
\end{enumerate}

$A=\begin{pmatrix}0&-i\\ i&0\end{pmatrix}$ について考える．
\begin{enumerate}
\item $U^\dagger A U=\begin{pmatrix}1&0\\0&-1\end{pmatrix}$ を満たすユニタリ行列 $U$ を 1 つ求めよ．また，同じ条件を満たすユニタリ行列の一般形を答えよ．
\item 実直交行列 $O$（$O^{T}O=I$，成分はすべて実数）で $O^{T}AO=\begin{pmatrix}1&0\\0&-1\end{pmatrix}$ となるものは存在しないことを示せ．
\item 実数 $\alpha$ に対して $R(\alpha)=\exp\!\left(-\dfrac{i\alpha}{2}A\right)$ を (1) の対角化を用いて計算し，$R(\alpha)$ が実行列になることを示せ．$R(\alpha)$ を実ベクトル $(x,y)^{T}$ に作用させると何が起こるか．また $R(2\pi)$ を求めよ．
\end{enumerate}

\begin{enumerate}
\item ユニタリ行列 $V$（$V^\dagger V=I$）の固有方程式 $V|n\rangle=v_n|n\rangle$（$\langle n|n\rangle=1$）について，$|v_n|=1$ であること，および $v_n\neq v_m$ なら $\langle n|m\rangle=0$ であることを示せ．
\item 行列 $B=\begin{pmatrix}1&1\\0&2\end{pmatrix}$ はエルミートでないが，固有値は実数である．固有値 $\lambda_1=1,\lambda_2=2$ に対する規格化された右固有ベクトル $|r_1\rangle,|r_2\rangle$（第 1 成分を正にとる）を求め，$|\langle r_1|r_2\rangle|$ を計算せよ．このとき $\sum_n|r_n\rangle\langle r_n|$ は単位行列になるか．
\item $B$ の左固有ベクトル（行ベクトル）$\langle l_n|$ を $\langle l_n|B=\lambda_n\langle l_n|$，$\langle l_n|r_m\rangle=\delta_{nm}$ を満たすように定める．$\langle l_1|,\langle l_2|$ を求め，$\sum_n|r_n\rangle\langle l_n|=I$ および $B=\sum_n\lambda_n|r_n\rangle\langle l_n|$ を確かめよ．
\end{enumerate}

$A,B,C$ をエルミート行列とする．
\begin{enumerate}
\item $AB$ がエルミートであるための必要十分条件は $[A,B]=0$ であることを示せ．また，$AB=H_1+iH_2$ を満たすエルミート行列 $H_1,H_2$ を $A,B$ で表せ．
\item $ABC$ がエルミートであるための必要十分条件は $ABC=CBA$ であることを示せ．
\item $A=\begin{pmatrix}0&1\\1&0\end{pmatrix}$，$B=\begin{pmatrix}0&-i\\ i&0\end{pmatrix}$，$C=\cos\theta\begin{pmatrix}0&1\\1&0\end{pmatrix}+\sin\theta\begin{pmatrix}1&0\\0&-1\end{pmatrix}$（$\theta$ は実数）のとき，$ABC$ を $B$ と $I$ を用いて表し，$ABC$ がエルミートになる $\theta$ をすべて求めよ．
\end{enumerate}

一次元で $\langle x|p\rangle=\dfrac{1}{\sqrt{2\pi\hbar}}e^{ipx/\hbar}$（$\langle p|p'\rangle=\delta(p-p')$）とし，運動量表示の波動関数を $\phi(p)=\langle p|\psi\rangle$ とする．ハミルトニアン $\hat H=\dfrac{\hat p^2}{2m}-V_0\delta(\hat x)$（$V_0>0$）の束縛状態（$E<0$）を，座標表示の微分方程式を使わずに求めたい．
\begin{enumerate}
\item 完全性 $\int dx\,|x\rangle\langle x|=1$ を用いて $\langle p|\delta(\hat x)|\psi\rangle=\dfrac{\psi(0)}{\sqrt{2\pi\hbar}}$，$\psi(0)=\dfrac{1}{\sqrt{2\pi\hbar}}\displaystyle\int_{-\infty}^{\infty}\phi(p)\,dp$ を示せ．
\item 運動量表示のシュレディンガー方程式が代数方程式になることを用いて，$\phi(p)$ の $p$ 依存性を決め，自己無撞着条件から束縛エネルギー $E$ を求めよ．束縛状態はいくつあるか．
\item 規格化された $\phi(p)$ を求め，それが $\psi(x)=\sqrt\kappa\,e^{-\kappa|x|}$（$\kappa=mV_0/\hbar^2$）のフーリエ変換 $\dfrac{1}{\sqrt{2\pi\hbar}}\displaystyle\int\psi(x)e^{-ipx/\hbar}dx$ と一致することを確かめよ．
\end{enumerate}

系が $\hat{\boldsymbol j}^2,\hat j_z$ の同時固有状態 $|jm\rangle$ にある．
\begin{enumerate}
\item $\langle\hat j_x\rangle=\langle\hat j_y\rangle=0$ を示し，$\langle\hat j_x^2\rangle$，$\langle\hat j_y^2\rangle$ を求めよ．
\item 単位ベクトル $\boldsymbol n=(\sin\theta\cos\varphi,\sin\theta\sin\varphi,\cos\theta)$ 方向の成分 $\hat j_n=\boldsymbol n\cdot\hat{\boldsymbol j}$ の平均 $\langle\hat j_n\rangle$ と分散 $(\Delta j_n)^2$ を求めよ．
\item 不確定性関係 $\Delta j_x\,\Delta j_y\ge\tfrac12|\langle\hat j_z\rangle|$ が $|jm\rangle$ で等号成立するのはどのような $m$ のときか．
\end{enumerate}

エルミート演算子 $\hat j_i$ が $[\hat j_i,\hat j_j]=i\varepsilon_{ijk}\hat j_k$ を満たし，有限次元空間に作用しているとする．
\begin{enumerate}
\item 一つの既約な（$\hat{\boldsymbol j}^2=j(j+1)$ の）梯子において $\hat j_z$ の固有値の最大値を $j$，最小値を $m_{\min}$ とする．$\hat j_+\hat j_-=\hat{\boldsymbol j}^2-\hat j_z^2+\hat j_z$ を用いて $m_{\min}=-j$ を示し，$2j$ が非負整数であることを導け．
\item 既約空間において $\mathrm{Tr}\,\hat j_z^2=\tfrac13j(j+1)(2j+1)$ を示せ．
\item ある 6 次元の（可約でもよい）表現で $\mathrm{Tr}\,\hat j_z^2=\tfrac52$ であった．この表現はどの $j$ の既約表現の直和か．また $\hat j_z$ の固有値をすべて重複度つきで答えよ．
\end{enumerate}

質量 $m$ の粒子が一次元ポテンシャル中にある．以下では「目安」ではなく厳密に成り立つ不等式だけを使う．
\begin{enumerate}
\item 任意の規格化状態で $\langle p^2\rangle\ge\dfrac{\hbar^2}{4\langle x^2\rangle}$ が成り立つことを，$\Delta x\Delta p\ge\hbar/2$ から示せ．
\item ハミルトニアン $H=\dfrac{p^2}{2m}+\lambda x^4$（$\lambda>0$）の基底エネルギー $E_0$ について，任意の状態で $\langle x^4\rangle\ge\langle x^2\rangle^2$ であることも使い，厳密な下限 $E_0\ge E_{\rm LB}$ を導け．$E_{\rm LB}$ を $\hbar,m,\lambda$ で表せ．
\item 同じ方法を調和振動子 $H=\dfrac{p^2}{2m}+\dfrac12m\omega^2x^2$ に使うと下限は真の基底エネルギーに一致する．一方，(2) の下限は真の値（$\hbar=m=\lambda=1$ の単位で数値計算すると $E_0\simeq0.6680$）より小さい．比 $E_{\rm LB}/E_0$ を求め，(2) で等号が成り立たない理由を (2) で使った二つの不等式の等号条件から説明せよ．
\end{enumerate}

実数 $t>0$ と実定数 $x_0,p_0$ に対して条件 $\{(\hat x-x_0)+it(\hat p-p_0)\}|\psi\rangle=0$ をみたす状態は $\Delta x\Delta p=\hbar/2$ を実現することが知られている．
\begin{enumerate}
\item この条件をみたす規格化波動関数 $\psi(x)$ を求め，$(\Delta x)^2$，$(\Delta p)^2$ を $t$ で表せ．さらに質量 $m$，角振動数 $\omega$ の調和振動子の消滅演算子 $\hat a=\sqrt{\dfrac{m\omega}{2\hbar}}\left(\hat x+\dfrac{i\hat p}{m\omega}\right)$ を用いると，$t=1/(m\omega)$ のときこの条件は $\hat a$ の固有値方程式になることを示し，固有値を求めよ．
\item $x_0=p_0=0$，一般の $t$ の状態を時刻 $0$ に調和振動子 $H=\dfrac{\hat p^2}{2m}+\dfrac12m\omega^2\hat x^2$ の中に置く．$s\equiv m\omega t$ として，時刻 $\tau$ での $\Delta x(\tau)\Delta p(\tau)$ を求めよ．（ハイゼンベルク描像で $\hat x(\tau)=\hat x\cos\omega\tau+\dfrac{\hat p}{m\omega}\sin\omega\tau$，$\hat p(\tau)=\hat p\cos\omega\tau-m\omega\hat x\sin\omega\tau$ を用いてよい．）
\item すべての時刻で最小不確定状態であり続けるための $t$ の条件を求めよ．また $s\ne1$ のとき $\Delta x\Delta p$ の最大値と，それをとる最初の時刻を求めよ．
\end{enumerate}

二次元平面内で，固定された陽子のまわりを質量 $m$ の電子が運動する模型 $H=\dfrac{p_x^2+p_y^2}{2m}-\dfrac{e^2}{r}$（$r=\sqrt{x^2+y^2}$）を考える．
\begin{enumerate}
\item 状態は等方的で $\langle x\rangle=\langle y\rangle=\langle p_x\rangle=\langle p_y\rangle=0$，$(\Delta x)^2=(\Delta y)^2=\rho^2/2$ とし，$\langle 1/r\rangle\approx1/\rho$ と見積もる．$\Delta x\Delta p_x\ge\hbar/2$，$\Delta y\Delta p_y\ge\hbar/2$ を用いてエネルギーを $\rho$ の関数として見積もり，基底エネルギーの見積もり値 $E_{\rm est}$ と対応する $\rho$ を求めよ．
\item $\psi=e^{-\kappa r}$ がこのハミルトニアンの厳密な固有関数となる $\kappa$ と，その固有値 $E_0$ を求めよ（二次元のラプラシアンの動径部分は $\partial_r^2+\frac1r\partial_r$）．$E_{\rm est}/E_0$ を求めよ．
\item クーロンポテンシャルを $-g/r^{s}$（$g>0$，$s>0$）に置き換える．(1) と同じ見積もりを行い，エネルギーが下に有界となる（電子が中心に落ち込まない）$s$ の範囲を求めよ．$s=2$ の場合はどうなるか．
\end{enumerate}

三次元で動径運動量を $\hat p_r=-i\hbar\dfrac1r\dfrac{\partial}{\partial r}r=-i\hbar\left(\dfrac{\partial}{\partial r}+\dfrac1r\right)$ と定める．期待値は $\langle A\rangle=\int\psi^*\hat A\psi\,d^3r$ とする．
\begin{enumerate}
\item $[\hat r,\hat p_r]=i\hbar$ を示せ．また，$r\psi\to0$（$r\to0$，$r\to\infty$）をみたす球対称な $\psi$ に対して $\langle p_r\rangle$ が実数であることを示し，$\Delta r\Delta p_r\ge\hbar/2$ を結論せよ．
\item 単純に $-i\hbar\,\partial/\partial r$ を動径運動量とすると，実数値の球対称な $\psi$ に対して $\langle-i\hbar\partial_r\rangle=i\hbar\langle 1/r\rangle$ となり，エルミートでないことを示せ．
\item 水素原子の基底状態 $\psi=\dfrac{1}{\sqrt{\pi a^3}}e^{-r/a}$ について $\Delta r$，$\Delta p_r$，$\Delta r\Delta p_r$ および $\langle -i\hbar\partial_r\rangle$ を求めよ．
\end{enumerate}

パウリ行列 $\sigma_x,\sigma_y,\sigma_z$ と $U_j(\theta)=e^{-i\theta\sigma_j}$（$j=x,y,z$）を考える．
\begin{enumerate}
\item $U_x(\theta)=\cos\theta\,1-i\sin\theta\,\sigma_x$ を用いて $U_x(\theta)^\dagger\sigma_zU_x(\theta)$ と $U_x(\theta)^\dagger\sigma_yU_x(\theta)$ を $\sigma_y,\sigma_z$ の一次結合で表せ．スピンベクトルは $x$ 軸まわりに角度いくら回転したことになるか．
\item $U_x(\pi/2)U_y(\pi/2)$ を $U_z$ を用いて表せ．また $U_z(\pi)$ を求め，「$2\pi$ 回転」で何が起こるか述べよ．
\item スピンが磁場中でハミルトニアン $H=\dfrac{\hbar\Omega}{2}\sigma_z$ に従って時間発展する．時刻 $0$ にスピンは $+x$ 向きの状態 $|+x\rangle=\frac1{\sqrt2}(1,1)^T$ にある．時刻 $T$ に瞬間的なパルス $U_x(\pi/2)$ を加え，さらに時間 $T$ 自由発展させる．時刻 $2T$ の状態を求め，それが $\Omega$ によらないことを示せ．$\Omega$ が粒子ごとにばらつく集団でこの操作が持つ意味を述べよ．
\end{enumerate}

大きさ $j_1,j_2$ の独立な角運動量を合成するとき，合成角運動量の大きさ $J$ は $|j_1-j_2|,\dots,j_1+j_2$ をそれぞれ1回ずつとる．以下では「全 $z$ 成分が $M$ である直積状態の数」$n(M)$ を手がかりに，3つ以上の合成を調べる．
\begin{enumerate}
\item 一般に，合成で大きさ $J$ の多重項が現れる回数 $N(J)$ は $N(J)=n(J)-n(J+1)$ で与えられることを説明せよ．
\item 3つのスピン1（$j_1=j_2=j_3=1$）を合成する．$n(M)$（$M=0,1,2,3$）を求め，各 $J$ の多重度 $N(J)$ を決定せよ．状態数の総和が $27$ になることも確かめよ．
\item (2) で $J=0$ の状態は何個あるか．その状態は3粒子のどの2つの入れ替えに対しても符号を変える（完全反対称である）ことを示せ．ただし，各スピン1の状態はデカルト基底 $|x\rangle,|y\rangle,|z\rangle$（ベクトルの成分のように回転する基底）で表してよい．
\end{enumerate}

2つのスピン $\frac12$ の間に交換相互作用 $\hat H=J\,\boldsymbol\sigma_1\cdot\boldsymbol\sigma_2$（$J>0$ は定数，$\boldsymbol\sigma_i$ はパウリ行列ベクトル）がはたらいている．$|{\uparrow}\rangle,|{\downarrow}\rangle$ を $\sigma_z$ の固有状態とする．
\begin{enumerate}
\item 2つのスピンの状態を入れ替える演算子 $\hat P_{12}$（$\hat P_{12}|a\rangle_1|b\rangle_2=|b\rangle_1|a\rangle_2$）が $\hat P_{12}=\frac12(1+\boldsymbol\sigma_1\cdot\boldsymbol\sigma_2)$ と書けることを，三重項・一重項状態に作用させて示せ．
\item 時刻 $t=0$ で状態が $|{\uparrow}\rangle_1|{\downarrow}\rangle_2$ であった．時刻 $t$ に $|{\downarrow}\rangle_1|{\uparrow}\rangle_2$ が観測される確率を求めよ．
\item 2つのスピンが完全に入れ替わる最初の時刻 $t_s$ を求めよ．また $t=t_s/2$ における粒子1の縮約密度行列を求め，このとき2スピンがどのような状態にあるか述べよ．
\end{enumerate}

独立な2つの角運動量 $\hat{\boldsymbol J}_1,\hat{\boldsymbol J}_2$（異なる番号の成分どうしは可換，$[\hat J_{1x},\hat J_{1y}]=i\hbar\hat J_{1z}$ など）の和を $\hat{\boldsymbol J}=\hat{\boldsymbol J}_1+\hat{\boldsymbol J}_2$ とする．
\begin{enumerate}
\item 交換子 $[\hat{\boldsymbol J}^2,\hat J_{1z}]$ を $\hat{\boldsymbol J}_1,\hat{\boldsymbol J}_2$ の成分で表せ．
\item $[\hat{\boldsymbol J}^2,\hat{\boldsymbol J}_1^{\,2}]=0$ を示せ．これと (1) から，合成状態 $|j_1j_2JM\rangle$ のラベルとして $j_1$ は使えるが $m_1$ は使えない理由を述べよ．
\item 2つのスピン $\frac12$ の場合，三重項 $|1,0\rangle=\frac1{\sqrt2}(|{\uparrow\downarrow}\rangle+|{\downarrow\uparrow}\rangle)$ と一重項 $|0,0\rangle=\frac1{\sqrt2}(|{\uparrow\downarrow}\rangle-|{\downarrow\uparrow}\rangle)$ の間の行列要素 $\langle1,0|\hat S_{1z}|0,0\rangle$ を求めよ．これは (1) の結果とどう整合するか．
\end{enumerate}

軌道角運動量 $l=1$ とスピン $s=\frac12$ をもつ電子を考える．直積状態を $|m_l\rangle|{\uparrow}\rangle$ などと書き，$\hbar$ を単位とする．昇降演算子の位相はコンドン＝ショートレイの規約に従うものとする．
\begin{enumerate}
\item 合成状態 $|j=\tfrac12,m=\tfrac12\rangle$ を，$|j=\tfrac32,m=\tfrac12\rangle$ との直交性を用いて直積状態の線形結合で表せ．ただし $|1\rangle|{\downarrow}\rangle$ の係数を正にとる．
\item この状態で $\hat L_z$ と $\hat S_z$ の期待値を求めよ．
\item 電子の磁気モーメントの $z$ 成分は $\hat\mu_z=-\mu_B(\hat L_z+2\hat S_z)/\hbar$ である．$|\tfrac12,\tfrac12\rangle$ での $\langle\hat\mu_z\rangle$ を求め，「スピン $\frac12$ をもつ自由電子」と比べて磁気モーメントが何倍になっているか答えよ．
\end{enumerate}

スピン $\frac12$ の粒子が中心力ポテンシャル中で軌道角運動量 $l\ (\ge1)$ の状態にあり，スピン軌道相互作用 $\lambda\,\hat{\boldsymbol l}\cdot\hat{\boldsymbol s}$（$\lambda$ は実定数）がはたらいている．
\begin{enumerate}
\item 全角運動量 $j=l\pm\frac12$ の各準位のエネルギーのずれ $\Delta E_\pm$ と，その間隔 $|\Delta E_+-\Delta E_-|$ を求めよ．
\item 縮退度で重みをつけた和 $\sum_j(2j+1)\Delta E_j$ が $0$ になること（重心則）を示し，それが $\mathrm{Tr}(\hat{\boldsymbol l}\cdot\hat{\boldsymbol s})=0$ と同値であることを説明せよ．
\item ある原子で，この相互作用によって1つの準位が2本に分裂し，上の準位は4重縮退，下の準位は6重縮退であった．準位間隔は $\Delta$ であった．$l$ と $\lambda$（符号を含む）を決定せよ．また，分裂前の準位から見た上下の準位のずれを $\Delta$ で表せ．
\end{enumerate}

2つのスピン1（$j_1=j_2=1$）を合成する．直積状態を $|m_1,m_2\rangle$ と書き，CG係数はコンドン＝ショートレイの規約（$|J,J\rangle$ の $|1,J-1\rangle$ 成分を正）に従う．
\begin{enumerate}
\item $M=0$ の合成状態 $|2,0\rangle,|1,0\rangle,|0,0\rangle$ を直積状態で表せ．
\item 粒子交換 $|m_1,m_2\rangle\to|m_2,m_1\rangle$ に対し，$J=2,1,0$ の各多重項は対称か反対称か答え，その規則を $(-1)^{J}$ の形でまとめよ．
\item 同種のスピン1ボソン2個が同じ空間軌道（交換について対称）に入り，スピン間に $\hat H=c\,\hat{\boldsymbol J}_1\cdot\hat{\boldsymbol J}_2/\hbar^2$（$c>0$）がはたらく．許される $J$ とそのエネルギー・縮退度を求め，基底状態で2粒子とも $m=0$ が観測される確率を求めよ．
\end{enumerate}

静磁場中の電荷 $e$，質量 $m$ の粒子を考える（ハミルトニアン $\hat H=\frac1{2m}(-i\hbar\nabla-\frac ec\boldsymbol A)^2$）．
\begin{enumerate}
\item $\rho=|\psi|^2$ に対する連続方程式 $\partial_t\rho+\nabla\cdot\boldsymbol j=0$ を満たす確率流密度 $\boldsymbol j$ を求めよ．
\item 一様磁場 $\boldsymbol B=(0,0,B)$（$e>0$，$B>0$）中で対称ゲージ $\boldsymbol A=\frac B2(-y,x,0)$ をとると，$xy$ 面内の
\[
\psi_0(x,y)=\frac{1}{\sqrt{2\pi\ell^2}}\exp\!\Big(-\frac{x^2+y^2}{4\ell^2}\Big),\qquad \ell=\sqrt{\frac{\hbar c}{eB}}
\]
はエネルギー $\hbar\omega/2$（$\omega=eB/mc$）の固有関数である．$\psi_0$ は実数であるにもかかわらず $\boldsymbol j\neq0$ であることを示し，$\boldsymbol j$ の向きと大きさを求めよ．
\item 電流密度 $e\boldsymbol j$ がつくる磁気モーメント $\mu_z=\frac1{2c}\int(\boldsymbol r\times e\boldsymbol j)_z\,d^2r$ を求め，$-\partial E_0/\partial B$ と一致することを確かめよ．
\end{enumerate}

一様磁場 $\boldsymbol B=(0,0,B)$ と一様電場 $\boldsymbol E=(E,0,0)$ の中の電荷 $e$，質量 $m$ の粒子（$\omega=eB/mc>0$）を量子力学で扱う．$\hat H=\frac{1}{2m}\hat{\boldsymbol\Pi}^2-eE\hat x$，$[\hat\Pi_x,\hat\Pi_y]=i\hbar eB/c$ である．
\begin{enumerate}
\item ハイゼンベルク方程式から $m\frac{d}{dt}\hat{\boldsymbol r}=\hat{\boldsymbol\Pi}$ と $\frac{d}{dt}\hat\Pi_x=eE+\frac{eB}{mc}\hat\Pi_y$，$\frac{d}{dt}\hat\Pi_y=-\frac{eB}{mc}\hat\Pi_x$ を導け．
\item $t=0$ で $\langle\hat x\rangle=\langle\hat y\rangle=0$，$\langle\hat{\boldsymbol\Pi}\rangle=0$ の任意の波束について，$\langle\hat x\rangle(t)$，$\langle\hat y\rangle(t)$ を求めよ．
\item 運動エネルギー演算子 $\hat K=\hat{\boldsymbol\Pi}^2/2m$ について $\frac{d}{dt}\hat K$ を求め，$\langle\hat K\rangle(t)-\langle\hat K\rangle(0)$ を (2) の結果で表せ．その最大値はいくらか．
\end{enumerate}

質量 $m$，角振動数 $\omega$ の 1 次元調和振動子 $\hat H_0=\dfrac{\hat p^2}{2m}+\dfrac12m\omega^2\hat x^2$ に摂動 $\hat H'=b\hat x^2$（$b$ は実定数）を加える．固有状態を $|n\rangle$，$\hat x=\sqrt{\dfrac{\hbar}{2m\omega}}(\hat a+\hat a^\dagger)$ とする．
\begin{enumerate}
\item 第 $n$ 準位の厳密なエネルギーを求めよ．
\item $\hat a,\hat a^\dagger$ を用いて 1 次・2 次摂動のエネルギー補正を計算し，(1) の展開と一致することを確かめよ．
\item (1) を $b$ のべき級数に展開したとき，その収束半径を求め，物理的意味を述べよ．
\end{enumerate}

区間 $0\le x\le L$ の無限に深い井戸に閉じ込められた質量 $m$ の粒子に，井戸の中心を基準とした一様な力の場による摂動 $\hat H'=F\,(x-L/2)$ を加える．非摂動状態は $\psi_n=\sqrt{2/L}\sin(n\pi x/L)$，$E_n^{(0)}=\dfrac{\hbar^2\pi^2n^2}{2mL^2}$．
\begin{enumerate}
\item 基底状態の 1 次補正が 0 であること，および 2 次補正の和に寄与するのは $n$ が偶数の状態だけであることを示せ．
\item $\langle\psi_2|\hat H'|\psi_1\rangle$ を求め，$n=2$ の 1 項だけで近似した 2 次補正 $E^{(2)}_{\rm 2lev}$ を求めよ．
\item 2 次補正の厳密な和は $E^{(2)}=-\dfrac{15-\pi^2}{24\pi^4}\dfrac{mF^2L^4}{\hbar^2}$ である（ダルガルノ・ルイスの方法で得られる）．$E^{(2)}_{\rm 2lev}/E^{(2)}$ を数値で求め，その理由を説明せよ．
\end{enumerate}

引力の湯川ポテンシャル $V(r)=-g\,\dfrac{e^{-\mu r}}{r}$（$g,\mu>0$）中の質量 $m$ の粒子を考える．$a_B\equiv\hbar^2/(mg)$ とおき，試行関数 $\psi(r)=e^{-r/a}$（$a>0$）を用いる．
\begin{enumerate}
\item 展開近似をせずに変分エネルギー $E(a)$ を求めよ．
\item $\mu a_B\ll1$ のとき，最小値を $\mu$ の 1 次まで求めよ．
\item この試行関数を使うと，$\mu a_B<1$ ならば束縛状態が存在することが証明できることを示せ．なお，数値計算による厳密な臨界値は $\mu a_B\approx1.19$ である．この差は何を意味するか．
\end{enumerate}

一次元ハミルトニアン $\hat H=\dfrac{\hat p^2}{2m}+V(x)$ の規格化された基底状態を $\psi_0(x)$，基底エネルギーを $E_0$ とする．
\begin{enumerate}
\item 試行関数 $\psi_\lambda(x)=\sqrt\lambda\,\psi_0(\lambda x)$ のエネルギー $E(\lambda)$ が $\lambda=1$ で停留することを用いて $2\langle T\rangle=\langle xV'(x)\rangle$ を示せ．
\item $V=g|x|^\nu$ のとき $\langle T\rangle$，$\langle V\rangle$ を $E_0$ で表せ．さらに，次元解析で $E_0\propto g^{2/(\nu+2)}$ となることとヘルマン–ファインマンの定理 $\partial E_0/\partial g=\langle|x|^\nu\rangle$ からも同じ結果が出ることを確かめよ．
\item $\hbar=m=g=1$ の単位で $V=gx^4$ の基底エネルギーが $E_0=0.667986$ であることを用いて，波動関数を求めずに $\langle x^4\rangle$ と $\langle p^2\rangle$ を求めよ．
\end{enumerate}

